// Service worker: cache the whole app on the first visit, then work fully offline.
// Built for weak data: files are fetched one by one with retries (a dropped connection does not
// throw away what was already downloaded), and anything missing is fetched again later.
// sw-files.js (generated by tools/build_sw_list.py) defines FMT_VERSION and FMT_FILES.
/* global importScripts */
importScripts('sw-files.js');
const CACHE = 'fmt-' + self.FMT_VERSION;
let filling = null;

function notify(msg) {
  return self.clients.matchAll({ includeUncontrolled: true }).then((cs) => cs.forEach((c) => c.postMessage(msg)));
}

async function missingFiles(cache) {
  const out = [];
  for (const f of self.FMT_FILES) {
    if (!(await cache.match(f))) out.push(f);
  }
  return out;
}

/** Download every file not yet cached (4 at a time, 3 tries each). Resolves true when complete. */
function fillCache() {
  if (filling) return filling;
  filling = (async () => {
    const cache = await caches.open(CACHE);
    const todo = await missingFiles(cache);
    let i = 0;
    const worker = async () => {
      while (i < todo.length) {
        const f = todo[i++];
        for (let attempt = 0; attempt < 3; attempt++) {
          try {
            const res = await fetch(new Request(f, { cache: 'reload' }));
            if (res.ok) { await cache.put(f, res); break; }
          } catch (e) { /* weak network: try again */ }
          await new Promise((r) => setTimeout(r, 800 * (attempt + 1)));
        }
      }
    };
    await Promise.all([worker(), worker(), worker(), worker()]);
    const left = await missingFiles(cache);
    if (!left.length) await notify({ type: 'cached', version: self.FMT_VERSION });
    return left.length === 0;
  })().finally(() => { filling = null; });
  return filling;
}

self.addEventListener('install', (event) => {
  // install never fails because of one dropped request; what is missing is fetched again later
  event.waitUntil(fillCache().catch(() => false).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.indexOf('fmt-') === 0 && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
      .then(() => fillCache()),
  );
});

// Cache first (instant, offline), refresh from the network in the background.
self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // the app makes no third-party requests
  // the archived v1.0 (…/v1.0/) is never cached or answered by this worker – not even the index.html fallback
  if (url.pathname.indexOf(new URL(self.registration.scope).pathname + 'v1.0/') === 0) return;
  event.respondWith(
    caches.open(CACHE).then((cache) =>
      cache.match(req, { ignoreSearch: true }).then((hit) => {
        const net = fetch(req)
          .then((res) => {
            if (res && res.ok && res.type === 'basic') cache.put(req, res.clone());
            return res;
          })
          .catch(() => hit || (req.mode === 'navigate' ? cache.match('index.html') : Response.error()));
        if (hit) { event.waitUntil(net.catch(() => null)); return hit; }
        return net;
      })),
  );
});

// The page asks "are you ready?" on every load; if files are still missing, keep downloading.
self.addEventListener('message', (event) => {
  if (event.data !== 'status') return;
  const reply = (ready) => event.source && event.source.postMessage({ type: 'status', ready, version: self.FMT_VERSION });
  event.waitUntil(caches.open(CACHE).then(missingFiles).then((left) => {
    reply(left.length === 0);
    if (left.length) return fillCache().then((ok) => { if (ok) reply(true); });
    return null;
  }));
});
